import 'package:bloc/bloc.dart';import 'package:meta/meta.dart';import 'package:zan/Core/Resources/app_constants.dart';import 'package:zan/Core/Models/product_details_model.dart';import '../../data/models/product_preview_entities.dart';import '../../domain/repositories/home_repo_impl.dart';part 'home_state.dart';class HomeCubit extends Cubit<HomeStateModel> {  HomeCubit(this.homeRepoImpl) : super(HomeStateModel());  final HomeRepoImpl homeRepoImpl;  Future<void> init() async {    _setLoading(AppConstants.kLoadingProductsFeatured, true);    _setLoading(AppConstants.kLoadingProductsPopular, true);    await _getProductIsFeatured();    await _getProductIsPopular();  }  Future<void> _getProductIsFeatured() async {    final response = await homeRepoImpl.getProductIsFeatured();    response.fold(      (failure) {},      (data) {        emit(state.copyWith(productsFeatured: data));      },    );    _setLoading(AppConstants.kLoadingProductsFeatured, false);  }  Future<void> _getProductIsPopular() async {    final response = await homeRepoImpl.getProductIsPopular();    response.fold(      (failure) {},      (data) {        emit(state.copyWith(productsPopular: data));      },    );    _setLoading(AppConstants.kLoadingProductsPopular, false);  }  Future<void> getProductByID(int id) async {    final response = await homeRepoImpl.getProductDetails(id);    response.fold(      (failure) {},      (data) {        emit(state.copyWith(productDetails: data));      },    );  }  void _setLoading(String key, bool value) {    emit(state.copyWith(      isLoading: {        ...state.isLoading,        key: value,      }, // Update specific key    ));  }}@immutableclass HomeStateModel {  final List<ProductPreviewEntities> productsFeatured;  final List<ProductPreviewEntities> productsPopular;  final ProductDetailsModel? productDetails;  final Map<String, bool> isLoading;  const HomeStateModel({    this.productsFeatured = const [],    this.productsPopular = const [],    this.isLoading = const {},    this.productDetails ,  });  HomeStateModel copyWith(      {List<ProductPreviewEntities>? productsFeatured,      List<ProductPreviewEntities>? productsPopular,      Map<String, bool>? isLoading,      ProductDetailsModel? productDetails}) {    return HomeStateModel(      productDetails: productDetails ?? this.productDetails,      productsFeatured: productsFeatured ?? this.productsFeatured,      productsPopular: productsPopular ?? this.productsPopular,      isLoading: isLoading ?? this.isLoading,    );  }}